    "조문": {"조문단위": {
        "조문번호": "2",
        "조문시행일자": "20260701",
        "조문변경여부": "N",
        "조문이동이전": "",
        "조문참고자료": "[전문개정 2009.2.6][2012.12.18 법률 제11579호에 의하여 2011.6.30 헌법불합치 결정된 이 조 제6호 라목을 개정함.]",
        "조문키": "0002001",
        "항": {"호": [
            {
                "호번호": "1.",
                "호내용": "1. \"광역도시계획\"이란 제10조에 따라 지정된 광역계획권의 장기발전방향을 제시하는 계획을 말한다."
            },
            {
                "호번호": "2.",
                "호내용": "2. \"도시ㆍ군계획\"이란 특별시ㆍ광역시ㆍ특별자치시ㆍ특별자치도ㆍ시 또는 군(광역시의 관할 구역에 있는 군은 제외한다. 이하 같다)의 관할 구역에 대하여 수립하는 공간구조와 발전방향에 대한 계획으로서 도시ㆍ군기본계획과 도시ㆍ군관리계획으로 구분한다."
            },
            {
                "호번호": "3.",
                "호내용": "3. \"도시ㆍ군기본계획\"이란 특별시ㆍ광역시ㆍ특별자치시ㆍ특별자치도ㆍ시 또는 군의 관할 구역 및 생활권에 대하여 기본적인 공간구조와 장기발전방향을 제시하는 종합계획으로서 도시ㆍ군관리계획 수립의 지침이 되는 계획을 말한다."
            },
            {
                "호번호": "4.",
                "호내용": "4. \"도시ㆍ군관리계획\"이란 특별시ㆍ광역시ㆍ특별자치시ㆍ특별자치도ㆍ시 또는 군의 개발ㆍ정비 및 보전을 위하여 수립하는 토지 이용, 교통, 환경, 경관, 안전, 산업, 정보통신, 보건, 복지, 안보, 문화 등에 관한 다음 각 목의 계획을 말한다.",
                "목": [
                    {
                        "목번호": "가.",
                        "목내용": "가. 용도지역ㆍ용도지구의 지정 또는 변경에 관한 계획"
                    },
                    {
                        "목번호": "나.",
                        "목내용": "나. 개발제한구역, 도시자연공원구역, 시가화조정구역(市街化調整區域), 수산자원보호구역의 지정 또는 변경에 관한 계획"
                    },
                    {
                        "목번호": "다.",
                        "목내용": "다. 기반시설의 설치ㆍ정비 또는 개량에 관한 계획"
                    },
                    {
                        "목번호": "라.",
                        "목내용": "라. 도시개발사업이나 정비사업에 관한 계획"
                    },
                    {
                        "목번호": "마.",
                        "목내용": "마. 지구단위계획구역의 지정 또는 변경에 관한 계획과 지구단위계획"
                    },
                    {
                        "목번호": "바.",
                        "목내용": "바. 삭제 <2024.2.6>"
                    },
                    {
                        "목번호": "사.",
                        "목내용": "사. 도시혁신구역의 지정 또는 변경에 관한 계획과 도시혁신계획"
                    },
                    {
                        "목번호": "아.",
                        "목내용": "아. 복합용도구역의 지정 또는 변경에 관한 계획과 복합용도계획"
                    },
                    {
                        "목번호": "자.",
                        "목내용": "자. 도시ㆍ군계획시설입체복합구역의 지정 또는 변경에 관한 계획"
                    }
                ]
            },
            {
                "호번호": "5.",
                "호내용": "5. \"지구단위계획\"이란 도시ㆍ군계획 수립 대상지역의 일부에 대하여 토지 이용을 합리화하고 그 기능을 증진시키며 미관을 개선하고 양호한 환경을 확보하며, 그 지역을 체계적ㆍ계획적으로 관리하기 위하여 수립하는 도시ㆍ군관리계획을 말한다."
            },
            {
                "호번호": "5.",
                "호가지번호": "2",
                "호내용": "5의2. 삭제<2024.2.6>"
            },
            {
                "호번호": "5.",
                "호가지번호": "3",
                "호내용": "5의3. \"성장관리계획\"이란 성장관리계획구역에서의 난개발을 방지하고 계획적인 개발을 유도하기 위하여 수립하는 계획을 말한다."
            },
            {
                "호번호": "5.",
                "호가지번호": "4",
                "호내용": "5의4. \"공간재구조화계획\"이란 토지의 이용 및 건축물이나 그 밖의 시설의 용도ㆍ건폐율ㆍ용적률ㆍ높이 등을 완화하는 용도구역의 효율적이고 계획적인 관리를 위하여 수립하는 계획을 말한다."
            },
            {
                "호번호": "5.",
                "호가지번호": "5",
                "호내용": "5의5. \"도시혁신계획\"이란 창의적이고 혁신적인 도시공간의 개발을 목적으로 도시혁신구역에서의 토지의 이용 및 건축물의 용도ㆍ건폐율ㆍ용적률ㆍ높이 등의 제한에 관한 사항을 따로 정하기 위하여 공간재구조화계획으로 결정하는 도시ㆍ군관리계획을 말한다."
            },
            {
                "호번호": "5.",
                "호가지번호": "6",
                "호내용": "5의6. \"복합용도계획\"이란 주거ㆍ상업ㆍ산업ㆍ교육ㆍ문화ㆍ의료 등 다양한 도시기능이 융복합된 공간의 조성을 목적으로 복합용도구역에서의 건축물의 용도별 구성비율 및 건폐율ㆍ용적률ㆍ높이 등의 제한에 관한 사항을 따로 정하기 위하여 공간재구조화계획으로 결정하는 도시ㆍ군관리계획을 말한다."
            },
            {
                "호번호": "6.",
                "호내용": "6. \"기반시설\"이란 다음 각 목의 시설로서 대통령령으로 정하는 시설을 말한다.",
                "목": [
                    {
                        "목번호": "가.",
                        "목내용": "가. 도로ㆍ철도ㆍ항만ㆍ공항ㆍ주차장 등 교통시설"
                    },
                    {
                        "목번호": "나.",
                        "목내용": "나. 광장ㆍ공원ㆍ녹지 등 공간시설"
                    },
                    {
                        "목번호": "다.",
                        "목내용": "다. 유통업무설비, 수도ㆍ전기ㆍ가스공급설비, 방송ㆍ통신시설, 공동구 등 유통ㆍ공급시설"
                    },
                    {
                        "목번호": "라.",
                        "목내용": "라. 학교ㆍ공공청사ㆍ문화시설 및 공공필요성이 인정되는 체육시설 등 공공ㆍ문화체육시설"
                    },
                    {
                        "목번호": "마.",
                        "목내용": "마. 하천ㆍ유수지(遊水池)ㆍ방화설비 등 방재시설"
                    },
                    {
                        "목번호": "바.",
                        "목내용": "바. 장사시설 등 보건위생시설"
                    },
                    {
                        "목번호": "사.",
                        "목내용": "사. 하수도, 폐기물처리 및 재활용시설, 빗물저장 및 이용시설 등 환경기초시설"
                    }
                ]
            },
            {
                "호번호": "7.",
                "호내용": "7. \"도시ㆍ군계획시설\"이란 기반시설 중 도시ㆍ군관리계획으로 결정된 시설을 말한다."
            },
            {
                "호번호": "8.",
                "호내용": "8. \"광역시설\"이란 기반시설 중 광역적인 정비체계가 필요한 다음 각 목의 시설로서 대통령령으로 정하는 시설을 말한다.",
                "목": [
                    {
                        "목번호": "가.",
                        "목내용": "가. 둘 이상의 특별시ㆍ광역시ㆍ특별자치시ㆍ특별자치도ㆍ시 또는 군의 관할 구역에 걸쳐 있는 시설"
                    },
                    {
                        "목번호": "나.",
                        "목내용": "나. 둘 이상의 특별시ㆍ광역시ㆍ특별자치시ㆍ특별자치도ㆍ시 또는 군이 공동으로 이용하는 시설"
                    }
                ]
            },
            {
                "호번호": "9.",
                "호내용": "9. \"공동구\"란 전기ㆍ가스ㆍ수도 등의 공급설비, 통신시설, 하수도시설 등 지하매설물을 공동 수용함으로써 미관의 개선, 도로구조의 보전 및 교통의 원활한 소통을 위하여 지하에 설치하는 시설물을 말한다."
            },
            {
                "호번호": "10.",
                "호내용": "10. \"도시ㆍ군계획시설사업\"이란 도시ㆍ군계획시설을 설치ㆍ정비 또는 개량하는 사업을 말한다."
            },
            {
                "호번호": "11.",
                "호내용": "11. \"도시ㆍ군계획사업\"이란 도시ㆍ군관리계획을 시행하기 위한 다음 각 목의 사업을 말한다.",
                "목": [
                    {
                        "목번호": "가.",
                        "목내용": "가. 도시ㆍ군계획시설사업"
                    },
                    {
                        "목번호": "나.",
                        "목내용": "나. 「도시개발법」에 따른 도시개발사업"
                    },
                    {
                        "목번호": "다.",
                        "목내용": "다. 「도시 및 주거환경정비법」에 따른 정비사업"
                    }
                ]
            },
            {
                "호번호": "12.",
                "호내용": "12. \"도시ㆍ군계획사업시행자\"란 이 법 또는 다른 법률에 따라 도시ㆍ군계획사업을 하는 자를 말한다."
            },
            {
                "호번호": "13.",
                "호내용": "13. \"공공시설\"이란 도로ㆍ공원ㆍ철도ㆍ수도, 그 밖에 대통령령으로 정하는 공공용 시설을 말한다."
            },
            {
                "호번호": "14.",
                "호내용": "14. \"국가계획\"이란 중앙행정기관이 법률에 따라 수립하거나 국가의 정책적인 목적을 이루기 위하여 수립하는 계획 중 제19조제1항제1호부터 제9호까지에 규정된 사항이나 도시ㆍ군관리계획으로 결정하여야 할 사항이 포함된 계획을 말한다."
            },
            {
                "호번호": "15.",
                "호내용": "15. \"용도지역\"이란 토지의 이용 및 건축물의 용도, 건폐율(「건축법」 제55조의 건폐율을 말한다. 이하 같다), 용적률(「건축법」 제56조의 용적률을 말한다. 이하 같다), 높이 등을 제한함으로써 토지를 경제적ㆍ효율적으로 이용하고 공공복리의 증진을 도모하기 위하여 서로 중복되지 아니하게 도시ㆍ군관리계획으로 결정하는 지역을 말한다."
            },
            {
                "호번호": "16.",
                "호내용": "16. \"용도지구\"란 토지의 이용 및 건축물의 용도ㆍ건폐율ㆍ용적률ㆍ높이 등에 대한 용도지역의 제한을 강화하거나 완화하여 적용함으로써 용도지역의 기능을 증진시키고 경관ㆍ안전 등을 도모하기 위하여 도시ㆍ군관리계획으로 결정하는 지역을 말한다."
            },
